import type {
  InnovationHubMainCards,
  PortfolioCardData,
  PortfolioPieChartData,
} from '../types';

export const BFF_VIEW_ID = 'innovation_innovation-hub_overview';
export const MAIN_CARDS_COMPONENT_ID = 'innovation-hub-overview-main-cards';
export const PORTFOLIO_BIG_NUMBERS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-big-numbers';
export const PORTFOLIO_PIE_CHARTS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-pie-charts';

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  value != null && typeof value === 'object';

export function getMainCards(data: unknown): InnovationHubMainCards | null {
  if (!isRecord(data)) return null;

  const componentData = data[MAIN_CARDS_COMPONENT_ID];

  return isRecord(componentData)
    ? (componentData as InnovationHubMainCards)
    : null;
}

export function getPortfolioArray<T>(
  data: unknown,
  componentId: string,
  dataKey: string,
): T[] {
  if (!isRecord(data)) return [];

  const componentData = data[componentId];
  const nestedData = isRecord(componentData)
    ? componentData[dataKey]
    : undefined;

  if (Array.isArray(nestedData)) {
    return nestedData as T[];
  }

  const flatData = data[dataKey];

  return Array.isArray(flatData) ? (flatData as T[]) : [];
}

export function getPortfolioBigNumbers(data: unknown): PortfolioCardData[] {
  return getPortfolioArray<PortfolioCardData>(
    data,
    PORTFOLIO_BIG_NUMBERS_COMPONENT_ID,
    'portfolio-big-numbers',
  );
}

export function getPortfolioPieCharts(data: unknown): PortfolioPieChartData[] {
  return getPortfolioArray<PortfolioPieChartData>(
    data,
    PORTFOLIO_PIE_CHARTS_COMPONENT_ID,
    'portfolio-pie-charts',
  );
}
